import json, re, sys, time
from urllib.parse import urlencode
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError

BASE='"'https://federation.ccdi.cancer.gov/api/v1'
UA='ccdi-footprint-metadata-summary/1.0'

def get(path, params=None, timeout=60):
    url = BASE + path
    if params:
        url += '?' + urlencode(params, doseq=True)
    req = Request(url, headers={'User-Agent': UA, 'Accept': 'application/json'})
    with urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8'))

def source_items(payload):
    if not isinstance(payload, list):
        raise ValueError('expected list payload')
    return payload

def rec_key(ref):
    if not isinstance(ref, dict): return None
    ns=ref.get('namespace') or {}
    return (ns.get('organization'), ns.get('name'), ref.get('name'))

def rec_key_str(ref):
    k=rec_key(ref)
    return '/'.join([str(x) for x in k]) if k and all(x is not None for x in k) else None

def size_int(v):
    if v is None: return None
    if isinstance(v, dict):
        # harmonized value wrapper
        return size_int(v.get('value'))
    if isinstance(v, (int,float)): return int(v)
    s=str(v).strip().replace(',', '')
    if not s or s.lower() in {'na','n/a','unknown','not reported','none','null'}: return None
    # handle plain byte strings and simple unit strings if present
    m=re.match(r'"'^([0-9]+(?:'"\\.[0-9]+)?)\\s*([KMGTPE]?i?B|[kmgtep]b|bytes?)?"'$'"', s, re.I)
    if not m:
        digits=re.sub(r'["'^0-9]'"', '', s)
        return int(digits) if digits else None
    n=float(m.group(1)); unit=(m.group(2) or '').lower()
    mult=1
    if unit in {'kb'}: mult=1000
    elif unit in {'mb'}: mult=1000**2
    elif unit in {'gb'}: mult=1000**3
    elif unit in {'tb'}: mult=1000**4
    elif unit in {'kib'}: mult=1024
    elif unit in {'mib'}: mult=1024**2
    elif unit in {'gib'}: mult=1024**3
    elif unit in {'tib'}: mult=1024**4
    return int(n*mult)

def file_size(f):
    # observed top-level harmonized "'`size`; fallback to metadata/unharmonized variants
    for path in [('"'size',), ('metadata','size'), ('metadata','unharmonized','file_size')]:
        cur=f
        ok=True
        for p in path:
            if isinstance(cur, dict) and p in cur: cur=cur[p]
            else: ok=False; break
        if ok:
            val=size_int(cur)
            if val is not None: return val
    return None

def page_summary(src_item):
    summ=src_item.get('summary') or {}
    counts=summ.get('counts') or src_item.get('counts') or {}
    return counts

# discover sources
info=source_items(get('/info'))
sources=[x.get('source') for x in info]
result={}
errors=[]
for src in sources:
    result[src]={
        'rnaseq_sample_ids': set(), 'sample_count_reported': None, 'sample_fetch_errors': [],
        'file_count': 0, 'size_bytes': 0, 'files_missing_size': 0, 'file_fetch_errors': [],
        'files_examined': 0, 'file_total_reported': None,
    }

# 1) Fetch RNA-Seq sample identifiers fully for relevant sources. Use per_page high but tolerate source limits.
for page in range(1, 500):
    payload=get('/sample', {'library_strategy':'RNA-Seq','page':page,'per_page':1000}, timeout=90)
    any_data=False
    done=True
    for item in source_items(payload):
        src=item.get('source')
        if not src in result: continue
        if 'errors' in item:
            if page == 1:
                result[src]['sample_fetch_errors'].extend(item['errors'])
            continue
        data=item.get('data') or []
        counts=page_summary(item)
        if counts.get('all') is not None:
            result[src]['sample_count_reported']=counts.get('all')
        if data:
            any_data=True
            for rec in data:
                k=rec_key_str(rec.get('id'))
                if k: result[src]['rnaseq_sample_ids'].add(k)
        current=counts.get('current', len(data))
        allc=counts.get('all')
        # If this source has more pages, global loop should continue.
        if data and (allc is None or page*1000 < int(allc)):
            done=False
    if done or not any_data:
        break
    time.sleep(0.05)

# 2) Stream files and join to sample ids. Sources without RNA-Seq samples still checked for errors only.
# CCDI-DCC has 1.6M files; use large per_page to minimize requests. Some nodes may cap per_page.
for page in range(1, 5000):
    payload=get('/file', {'page':page,'per_page':5000}, timeout=120)
    any_data=False
    done=True
    for item in source_items(payload):
        src=item.get('source')
        if src not in result: continue
        if 'errors' in item:
            if page == 1:
                result[src]['file_fetch_errors'].extend(item['errors'])
            continue
        data=item.get('data') or []
        counts=page_summary(item)
        if counts.get('all') is not None:
            result[src]['file_total_reported']=counts.get('all')
        if data:
            any_data=True
        result[src]['files_examined'] += len(data)
        rnaseq_ids=result[src]['rnaseq_sample_ids']
        if rnaseq_ids:
            for f in data:
                samples=f.get('samples') or []
                match=False
                for s in samples:
                    ks=rec_key_str(s)
                    if ks in rnaseq_ids:
                        match=True; break
                if match:
                    result[src]['file_count'] += 1
                    sz=file_size(f)
                    if sz is None:
                        result[src]['files_missing_size'] += 1
                    else:
                        result[src]['size_bytes'] += sz
        allc=counts.get('all')
        # Continue until every source with data has been fully paged.
        if data and (allc is None or page*5000 < int(allc)):
            done=False
    if page % 20 == 0:
        print(f'page {page}', file=sys.stderr, flush=True)
    if done or not any_data:
        break
    time.sleep(0.02)

# serialize sets as counts and sorted first few examples
out=[]
for src in sources:
    r=result[src]
    out.append({
        'source': src,
        'rnaseq_sample_ids_fetched': len(r['rnaseq_sample_ids']),
        'sample_count_reported_by_filter': r['sample_count_reported'],
        'file_count_linked_to_rnaseq_samples': r['file_count'],
        'data_size_bytes': r['size_bytes'],
        'data_size_gib': r['size_bytes']/(1024**3),
        'files_missing_size': r['files_missing_size'],
        'files_examined': r['files_examined'],
        'file_total_reported': r['file_total_reported'],
        'sample_fetch_errors': r['sample_fetch_errors'],
        'file_fetch_errors': r['file_fetch_errors'],
    })
print(json.dumps(out, indent=2))
